//! YAML frontmatter parsing against the `yaml` npm package (2.9.0) that TypeScript pi uses:
//! error messages (with positions and source excerpts) and parsed values for a hand-written
//! corpus of invalid frontmatter plus a deterministic fuzz corpus. Fixture generated by
//! `scripts/golden/gen-yaml.mjs`.

use pi_ai::utils::js_json::js_json_stringify;
use pi_coding_agent::parse_frontmatter;
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    yaml: String,
    error: Option<String>,
    json: Option<serde_json::Value>,
    #[serde(default)]
    approx: bool,
    #[serde(default)]
    cyclic: bool,
}

#[test]
fn frontmatter_matches_the_yaml_package() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/golden/yaml_frontmatter.json");
    let cases: Vec<Case> = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    assert!(cases.len() > 2000);
    let mut failures = Vec::new();
    for case in &cases {
        let content = format!("---\n{}\n---\nBody", case.yaml);
        let result = parse_frontmatter(&content);
        match (&case.error, result) {
            (Some(expected), Err(err)) => {
                if err.to_string() != *expected {
                    failures.push(format!("{:?}\n  expected error {expected:?}\n  got error      {:?}", case.yaml, err.to_string()));
                }
            }
            (Some(expected), Ok(parsed)) => {
                failures.push(format!("{:?}\n  expected error {expected:?}\n  got value {}", case.yaml, parsed.frontmatter));
            }
            (None, Err(err)) => {
                failures.push(format!("{:?}\n  expected value {:?}\n  got error {:?}", case.yaml, case.json, err.to_string()));
            }
            (None, Ok(parsed)) => {
                if case.approx || case.cyclic {
                    continue;
                }
                let expected = match &case.json {
                    Some(serde_json::Value::String(s)) => s.clone(),
                    other => panic!("bad fixture json {other:?}"),
                };
                let actual = js_json_stringify(&parsed.frontmatter);
                if actual != expected {
                    failures.push(format!("{:?}\n  expected value {expected}\n  got value      {actual}", case.yaml));
                }
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.iter().take(25).cloned().collect::<Vec<_>>().join("\n")
    );
}
